const std = @import("std");

/// Each subcommand is an independent module rooted at `src/<name>/<name>.zig`
/// and exposes `pub fn run(gpa, in, out) !void`. The names here must match the
/// subcommand names dispatched in `src/main.zig`.
const subcommands = [_][]const u8{ "wordfreq", "lru", "calc" };

pub fn build(b: *std.Build) void {
    const target = b.standardTargetOptions(.{});
    const optimize = b.standardOptimizeOption(.{});

    const exe_mod = b.createModule(.{
        .root_source_file = b.path("src/main.zig"),
        .target = target,
        .optimize = optimize,
    });

    const test_step = b.step("test", "Run unit tests");

    for (subcommands) |name| {
        const mod = b.createModule(.{
            .root_source_file = b.path(b.fmt("src/{s}/{s}.zig", .{ name, name })),
            .target = target,
            .optimize = optimize,
        });
        exe_mod.addImport(name, mod);

        const mod_tests = b.addTest(.{ .name = name, .root_module = mod });
        test_step.dependOn(&b.addRunArtifact(mod_tests).step);
    }

    const exe = b.addExecutable(.{
        .name = "app",
        .root_module = exe_mod,
    });
    b.installArtifact(exe);

    const exe_tests = b.addTest(.{ .name = "main", .root_module = exe_mod });
    test_step.dependOn(&b.addRunArtifact(exe_tests).step);

    const run_cmd = b.addRunArtifact(exe);
    run_cmd.step.dependOn(b.getInstallStep());
    if (b.args) |args| run_cmd.addArgs(args);
    const run_step = b.step("run", "Run the app");
    run_step.dependOn(&run_cmd.step);
}

//! Evaluates one `calc` expression (see SPEC.md) over signed 64-bit integers.
//!
//! Parsing is an iterative operator-precedence (shunting-yard) algorithm with
//! explicit stacks, so arbitrarily deep nesting of parentheses or unary minus
//! cannot overflow the call stack. The stacks are kept between calls so that
//! evaluating many lines reuses their capacity.

const std = @import("std");
const Allocator = std.mem.Allocator;
const math = std.math;

const Evaluator = @This();

gpa: Allocator,
values: std.ArrayList(i64) = .empty,
ops: std.ArrayList(Op) = .empty,

pub const Error = error{
    /// The input does not match the grammar.
    Syntax,
    /// Division or remainder by zero.
    DivisionByZero,
    /// A literal or intermediate result outside the range of `i64`.
    Overflow,
} || Allocator.Error;

const Op = enum {
    add,
    sub,
    mul,
    div,
    rem,
    neg,
    /// Open parenthesis: a barrier that no reduction crosses.
    lparen,

    fn precedence(op: Op) u8 {
        return switch (op) {
            .lparen => 0,
            .add, .sub => 1,
            .mul, .div, .rem => 2,
            .neg => 3,
        };
    }

    fn fromBinary(c: u8) ?Op {
        return switch (c) {
            '+' => .add,
            '-' => .sub,
            '*' => .mul,
            '/' => .div,
            '%' => .rem,
            else => null,
        };
    }
};

pub fn init(gpa: Allocator) Evaluator {
    return .{ .gpa = gpa };
}

pub fn deinit(e: *Evaluator) void {
    e.values.deinit(e.gpa);
    e.ops.deinit(e.gpa);
    e.* = undefined;
}

/// Returns the value of `source`, which must hold a complete expression.
pub fn eval(e: *Evaluator, source: []const u8) Error!i64 {
    e.values.clearRetainingCapacity();
    e.ops.clearRetainingCapacity();

    // Whether the next token must start an operand (number, '(' or unary
    // '-') rather than continue one (binary operator or ')').
    var expect_operand = true;
    var i: usize = 0;
    while (i < source.len) {
        const c = source[i];
        if (c == ' ' or c == '\t') {
            i += 1;
            continue;
        }
        if (expect_operand) {
            switch (c) {
                '-' => try e.ops.append(e.gpa, .neg),
                '(' => try e.ops.append(e.gpa, .lparen),
                '0'...'9' => {
                    var value: i64 = 0;
                    while (i < source.len and std.ascii.isDigit(source[i])) : (i += 1) {
                        value = try math.add(i64, try math.mul(i64, value, 10), source[i] - '0');
                    }
                    try e.values.append(e.gpa, value);
                    expect_operand = false;
                    continue;
                },
                else => return error.Syntax,
            }
        } else if (c == ')') {
            try e.reduceWhile(0);
            if (e.ops.pop() != .lparen) return error.Syntax;
        } else {
            const op = Op.fromBinary(c) orelse return error.Syntax;
            // Left associativity: reduce operators of equal precedence too.
            try e.reduceWhile(op.precedence() - 1);
            try e.ops.append(e.gpa, op);
            expect_operand = true;
        }
        i += 1;
    }
    if (expect_operand) return error.Syntax;

    try e.reduceWhile(0);
    if (e.ops.items.len != 0) return error.Syntax; // unclosed '('
    std.debug.assert(e.values.items.len == 1);
    return e.values.items[0];
}

/// Applies stacked operators while their precedence exceeds `min`.
fn reduceWhile(e: *Evaluator, min: u8) Error!void {
    while (e.ops.items.len > 0) {
        const op = e.ops.getLast();
        if (op.precedence() <= min) break;
        _ = e.ops.pop();
        if (op == .neg) {
            const top = &e.values.items[e.values.items.len - 1];
            top.* = try math.negate(top.*);
        } else {
            const rhs = e.values.pop().?;
            const lhs = &e.values.items[e.values.items.len - 1];
            lhs.* = try apply(op, lhs.*, rhs);
        }
    }
}

fn apply(op: Op, lhs: i64, rhs: i64) Error!i64 {
    return switch (op) {
        .add => math.add(i64, lhs, rhs),
        .sub => math.sub(i64, lhs, rhs),
        .mul => math.mul(i64, lhs, rhs),
        .div => {
            if (rhs == 0) return error.DivisionByZero;
            if (lhs == math.minInt(i64) and rhs == -1) return error.Overflow;
            return @divTrunc(lhs, rhs);
        },
        .rem => {
            if (rhs == 0) return error.DivisionByZero;
            // The quotient may overflow, but the remainder is always 0.
            if (rhs == -1) return 0;
            return @rem(lhs, rhs);
        },
        .neg, .lparen => unreachable,
    };
}

fn expectValue(expected: i64, source: []const u8) !void {
    var e: Evaluator = .init(std.testing.allocator);
    defer e.deinit();
    try std.testing.expectEqual(expected, try e.eval(source));
}

fn expectError(expected: Error, source: []const u8) !void {
    var e: Evaluator = .init(std.testing.allocator);
    defer e.deinit();
    try std.testing.expectError(expected, e.eval(source));
}

test "precedence and associativity" {
    try expectValue(7, "1 + 2 * 3");
    try expectValue(9, "(1 + 2) * 3");
    try expectValue(5, "1 + 2 * 3 - 4 / 2 % 3");
    try expectValue(3, "10 - 4 - 3");
    try expectValue(2, "100 / 10 / 5");
    try expectValue(70, "2*(3+4)*5");
    try expectValue(42, "\t ( ( 42 ) ) ");
}

test "unary minus" {
    try expectValue(5, "--5");
    try expectValue(-6, "2 * -3");
    try expectValue(3, "1 - -2");
    try expectValue(-5, "-(2 + 3)");
    try expectValue(-6, "-2 * 3");
    try expectValue(-9223372036854775807 - 1, "-9223372036854775807 - 1");
}

test "division and remainder" {
    try expectValue(-3, "-7 / 2");
    try expectValue(-1, "-7 % 3");
    try expectValue(1, "7 % -3");
    try expectValue(0, "(-9223372036854775807 - 1) % -1");
    try expectError(error.DivisionByZero, "1 / 0");
    try expectError(error.DivisionByZero, "5 % (2 - 2)");
}

test "overflow" {
    try expectValue(9223372036854775807, "0009223372036854775807");
    try expectError(error.Overflow, "9223372036854775808");
    try expectError(error.Overflow, "-9223372036854775808");
    try expectError(error.Overflow, "9223372036854775807 + 1");
    try expectError(error.Overflow, "-(-9223372036854775807 - 1)");
    try expectError(error.Overflow, "(-9223372036854775807 - 1) / -1");
    try expectError(error.Overflow, "4294967296 * 4294967296");
}

test "syntax errors" {
    for ([_][]const u8{ "1 +", "abc", "()", "1 2", "+1", "(1 + 2", "1 + 2)", ")", "1 (2)", "2 -", "1 +* 2", "1\r" }) |source| {
        try expectError(error.Syntax, source);
    }
}

test "deep nesting" {
    const depth = 100_000;
    const source = try std.testing.allocator.alloc(u8, 2 * depth + 1);
    defer std.testing.allocator.free(source);
    @memset(source[0..depth], '(');
    source[depth] = '7';
    @memset(source[depth + 1 ..], ')');
    try expectValue(7, source);
    @memset(source[0..depth], '-');
    try expectValue(7, source[0 .. depth + 1]);
}

//! `app calc` — see the "calc" section of SPEC.md.

const std = @import("std");
const Allocator = std.mem.Allocator;
const Io = std.Io;

const Evaluator = @import("Evaluator.zig");

/// 64-bit signed integer expression evaluator: evaluate each line of `in`.
///
/// `in` is standard input and `out` is buffered standard output; the caller
/// flushes `out` after this returns. `gpa` is a general-purpose allocator.
pub fn run(gpa: Allocator, in: *Io.Reader, out: *Io.Writer) !void {
    var evaluator: Evaluator = .init(gpa);
    defer evaluator.deinit();
    var long_line: Io.Writer.Allocating = .init(gpa);
    defer long_line.deinit();

    while (try nextLine(in, &long_line)) |line| {
        if (std.mem.trim(u8, line, " \t").len == 0) continue;
        if (evaluator.eval(line)) |value| {
            try out.print("{d}\n", .{value});
        } else |err| switch (err) {
            error.OutOfMemory => return error.OutOfMemory,
            error.Syntax, error.DivisionByZero, error.Overflow => try out.writeAll("error\n"),
        }
    }
}

/// Returns the next line of `in` without its '\n', or null at end of stream.
///
/// Lines that fit in the reader's buffer are returned in place; longer ones
/// are accumulated in `long_line`. The result is valid until the next call.
fn nextLine(in: *Io.Reader, long_line: *Io.Writer.Allocating) !?[]const u8 {
    if (in.takeDelimiter('\n')) |line| {
        return line;
    } else |err| switch (err) {
        error.StreamTooLong => {},
        error.ReadFailed => return error.ReadFailed,
    }

    long_line.clearRetainingCapacity();
    // The only failure of an allocating writer is running out of memory.
    _ = in.streamDelimiterEnding(&long_line.writer, '\n') catch |err| switch (err) {
        error.WriteFailed => return error.OutOfMemory,
        error.ReadFailed => return error.ReadFailed,
    };
    // Discard the delimiter, unless the stream ended without one.
    if (in.bufferedLen() > 0) in.toss(1);
    return long_line.written();
}

fn expectOutput(input: []const u8, expected: []const u8) !void {
    var in: Io.Reader = .fixed(input);
    var buf: [256]u8 = undefined;
    var out: Io.Writer = .fixed(&buf);
    try run(std.testing.allocator, &in, &out);
    try std.testing.expectEqualStrings(expected, out.buffered());
}

test run {
    try expectOutput("", "");
    try expectOutput(
        "1 + 2 * 3\n-7 / 2\n(1 + 2\n9223372036854775807 + 1\n",
        "7\n-3\nerror\nerror\n",
    );
    try expectOutput("\n  42  \n\t\n1+1", "42\n2\n");
}

test "lines longer than the reader buffer" {
    const input = "1 + 2 + 3\n" ++ "(" ** 40 ++ "4" ++ ")" ** 40 ++ "\n5 / 0\n" ++ "-" ** 50 ++ "6";
    var backing: [16]u8 = undefined;
    var in: Io.Reader = .fixed(input);
    var limited = in.limited(.unlimited, &backing);
    var buf: [64]u8 = undefined;
    var out: Io.Writer = .fixed(&buf);
    try run(std.testing.allocator, &limited.interface, &out);
    try std.testing.expectEqualStrings("6\n4\nerror\n6\n", out.buffered());
}

test {
    _ = Evaluator;
}

//! A bounded least-recently-used cache from string keys to string values.
//!
//! Entries live in a pool of fixed-size nodes, threaded on an intrusive
//! doubly-linked list ordered from most (`head`) to least (`tail`) recently
//! used. A hash set of node indices, hashed and compared by the node's key,
//! finds the node of a key. Every operation runs in O(1) expected time, and
//! the pool never holds more than `capacity` nodes: an evicted or deleted
//! node is recycled through a free list.
//!
//! The set is an array hash map rather than `std.HashMapUnmanaged`: the latter
//! deletes with tombstones, which a long run of insertions and evictions piles
//! up until lookups degrade to linear scans. The array hash map removes
//! entries without leaving tombstones behind.

const std = @import("std");
const Allocator = std.mem.Allocator;
const assert = std.debug.assert;

const Cache = @This();

pub const max_capacity = 1_000_000;
/// The maximum length in bytes of a key or a value.
pub const max_token_len = 64;

const Index = u32;
const none: Index = std.math.maxInt(Index);

const Node = struct {
    /// Towards `head` (more recently used); on the free list, unused.
    prev: Index,
    /// Towards `tail` (less recently used); on the free list, the next free node.
    next: Index,
    key_len: u8,
    value_len: u8,
    key_buf: [max_token_len]u8,
    value_buf: [max_token_len]u8,

    fn key(node: *const Node) []const u8 {
        return node.key_buf[0..node.key_len];
    }

    fn value(node: *const Node) []const u8 {
        return node.value_buf[0..node.value_len];
    }

    fn setKey(node: *Node, k: []const u8) void {
        @memcpy(node.key_buf[0..k.len], k);
        node.key_len = @intCast(k.len);
    }

    fn setValue(node: *Node, v: []const u8) void {
        @memcpy(node.value_buf[0..v.len], v);
        node.value_len = @intCast(v.len);
    }
};

fn hashKey(k: []const u8) u32 {
    return @truncate(std.hash.Wyhash.hash(0, k));
}

/// Hashes and compares stored node indices by their keys.
const IndexContext = struct {
    nodes: []const Node,

    pub fn hash(ctx: IndexContext, index: Index) u32 {
        return hashKey(ctx.nodes[index].key());
    }

    pub fn eql(ctx: IndexContext, a: Index, b: Index, b_index: usize) bool {
        _ = ctx;
        _ = b_index;
        // Each key is held by exactly one node.
        return a == b;
    }
};

/// Looks up stored node indices by key.
const KeyAdapter = struct {
    nodes: []const Node,

    pub fn hash(_: KeyAdapter, k: []const u8) u32 {
        return hashKey(k);
    }

    pub fn eql(ctx: KeyAdapter, k: []const u8, index: Index, b_index: usize) bool {
        _ = b_index;
        return std.mem.eql(u8, k, ctx.nodes[index].key());
    }
};

/// Stores each key's hash, so probing compares hashes before touching a node.
const IndexSet = std.array_hash_map.Custom(Index, void, IndexContext, true);

capacity: u32,
nodes: std.ArrayList(Node) = .empty,
map: IndexSet = .empty,
head: Index = none,
tail: Index = none,
free: Index = none,

pub fn init(capacity: u32) Cache {
    assert(capacity >= 1 and capacity <= max_capacity);
    return .{ .capacity = capacity };
}

pub fn deinit(cache: *Cache, gpa: Allocator) void {
    cache.map.deinit(gpa);
    cache.nodes.deinit(gpa);
    cache.* = undefined;
}

/// The number of keys held.
pub fn size(cache: *const Cache) u32 {
    return @intCast(cache.map.count());
}

/// Returns the value of `key` and marks it most recently used, or returns
/// null if absent. The slice is valid until the next modification.
pub fn get(cache: *Cache, key: []const u8) ?[]const u8 {
    const index = cache.find(key) orelse return null;
    cache.promote(index);
    return cache.nodes.items[index].value();
}

/// Removes `key`; returns whether it was present.
pub fn del(cache: *Cache, key: []const u8) bool {
    const kv = cache.map.fetchSwapRemoveContextAdapted(key, cache.keyAdapter(), cache.indexContext()) orelse
        return false;
    cache.unlink(kv.key);
    cache.release(kv.key);
    return true;
}

/// Inserts or overwrites `key`, marks it most recently used, and evicts the
/// least recently used key if the cache would otherwise exceed its capacity.
pub fn set(cache: *Cache, gpa: Allocator, key: []const u8, value: []const u8) Allocator.Error!void {
    assert(key.len >= 1 and key.len <= max_token_len);
    assert(value.len <= max_token_len);

    if (cache.find(key)) |index| {
        cache.nodes.items[index].setValue(value);
        cache.promote(index);
        return;
    }

    // Make room before allocating, so the pool stays within capacity.
    if (cache.size() == cache.capacity) cache.evict();

    const index = try cache.acquire(gpa);
    errdefer cache.release(index);
    const node = &cache.nodes.items[index];
    node.setKey(key);
    node.setValue(value);

    const gop = try cache.map.getOrPutContextAdapted(gpa, key, cache.keyAdapter(), cache.indexContext());
    assert(!gop.found_existing);
    gop.key_ptr.* = index;
    cache.pushFront(index);
}

fn find(cache: *const Cache, key: []const u8) ?Index {
    return cache.map.getKeyAdapted(key, cache.keyAdapter());
}

fn evict(cache: *Cache) void {
    const index = cache.tail;
    assert(index != none);
    const removed = cache.map.swapRemoveContext(index, cache.indexContext());
    assert(removed);
    cache.unlink(index);
    cache.release(index);
}

fn keyAdapter(cache: *const Cache) KeyAdapter {
    return .{ .nodes = cache.nodes.items };
}

fn indexContext(cache: *const Cache) IndexContext {
    return .{ .nodes = cache.nodes.items };
}

/// Takes a node from the free list, or grows the pool.
fn acquire(cache: *Cache, gpa: Allocator) Allocator.Error!Index {
    if (cache.free != none) {
        const index = cache.free;
        cache.free = cache.nodes.items[index].next;
        return index;
    }
    const index: Index = @intCast(cache.nodes.items.len);
    _ = try cache.nodes.addOne(gpa);
    return index;
}

fn release(cache: *Cache, index: Index) void {
    cache.nodes.items[index].next = cache.free;
    cache.free = index;
}

fn promote(cache: *Cache, index: Index) void {
    if (cache.head == index) return;
    cache.unlink(index);
    cache.pushFront(index);
}

fn pushFront(cache: *Cache, index: Index) void {
    const node = &cache.nodes.items[index];
    node.prev = none;
    node.next = cache.head;
    if (cache.head != none) {
        cache.nodes.items[cache.head].prev = index;
    } else {
        cache.tail = index;
    }
    cache.head = index;
}

fn unlink(cache: *Cache, index: Index) void {
    const nodes = cache.nodes.items;
    const node = &nodes[index];
    if (node.prev != none) nodes[node.prev].next = node.next else cache.head = node.next;
    if (node.next != none) nodes[node.next].prev = node.prev else cache.tail = node.prev;
}

test "eviction order follows recency" {
    const gpa = std.testing.allocator;
    var cache: Cache = .init(2);
    defer cache.deinit(gpa);

    try cache.set(gpa, "a", "1");
    try cache.set(gpa, "b", "2");
    try std.testing.expectEqualStrings("1", cache.get("a").?);
    try cache.set(gpa, "c", "3");
    try std.testing.expectEqual(null, cache.get("b"));
    try std.testing.expectEqualStrings("1", cache.get("a").?);
    try std.testing.expectEqualStrings("3", cache.get("c").?);
    try std.testing.expectEqual(2, cache.size());
}

test "pool never exceeds capacity" {
    const gpa = std.testing.allocator;
    var cache: Cache = .init(3);
    defer cache.deinit(gpa);

    var buf: [16]u8 = undefined;
    for (0..1000) |i| {
        const key = try std.fmt.bufPrint(&buf, "k{d}", .{i % 17});
        if (i % 5 == 0) {
            _ = cache.del(key);
        } else {
            try cache.set(gpa, key, key);
        }
        try std.testing.expect(cache.size() <= 3);
        try std.testing.expect(cache.nodes.items.len <= 3);
    }
}

test "max length keys and values" {
    const gpa = std.testing.allocator;
    var cache: Cache = .init(1);
    defer cache.deinit(gpa);

    const long = "x" ** max_token_len;
    try cache.set(gpa, long, long);
    try std.testing.expectEqualStrings(long, cache.get(long).?);
    try std.testing.expect(cache.del(long));
    try std.testing.expect(!cache.del(long));
    try std.testing.expectEqual(0, cache.size());
}

//! `app lru` — see the "lru" section of SPEC.md.
//!
//! The first input line is the cache capacity; every later line is a `SET`,
//! `GET`, `DEL` or `SIZE` command, executed in O(1) expected time.

const std = @import("std");
const Allocator = std.mem.Allocator;
const Io = std.Io;

pub const Cache = @import("Cache.zig");

pub const Error = error{
    MissingCapacity,
    InvalidCapacity,
    InvalidCommand,
} || Allocator.Error || Io.Reader.DelimiterError || Io.Writer.Error;

/// LRU cache simulator: execute the commands read from `in`.
///
/// `in` is standard input and `out` is buffered standard output; the caller
/// flushes `out` after this returns. `gpa` is a general-purpose allocator.
pub fn run(gpa: Allocator, in: *Io.Reader, out: *Io.Writer) Error!void {
    const first = try in.takeDelimiter('\n') orelse return error.MissingCapacity;
    const capacity = parseCapacity(first) orelse return error.InvalidCapacity;

    var cache: Cache = .init(capacity);
    defer cache.deinit(gpa);

    while (try in.takeDelimiter('\n')) |raw| {
        const line = std.mem.trimEnd(u8, raw, "\r");
        if (line.len == 0) continue;
        try execute(gpa, &cache, line, out);
    }
}

fn parseCapacity(line: []const u8) ?u32 {
    const text = std.mem.trim(u8, line, " \t\r");
    const capacity = std.fmt.parseUnsigned(u32, text, 10) catch return null;
    if (capacity < 1 or capacity > Cache.max_capacity) return null;
    return capacity;
}

const Command = enum { SET, GET, DEL, SIZE };

fn execute(gpa: Allocator, cache: *Cache, line: []const u8, out: *Io.Writer) Error!void {
    var tokens = std.mem.splitScalar(u8, line, ' ');
    const name = tokens.first();
    const command = std.meta.stringToEnum(Command, name) orelse return error.InvalidCommand;
    switch (command) {
        .SET => {
            const key = try token(&tokens);
            const value = try token(&tokens);
            try end(&tokens);
            try cache.set(gpa, key, value);
        },
        .GET => {
            const key = try token(&tokens);
            try end(&tokens);
            try out.print("{s}\n", .{cache.get(key) orelse "NULL"});
        },
        .DEL => {
            const key = try token(&tokens);
            try end(&tokens);
            try out.writeAll(if (cache.del(key)) "1\n" else "0\n");
        },
        .SIZE => {
            try end(&tokens);
            try out.print("{d}\n", .{cache.size()});
        },
    }
}

/// Returns the next key or value token, which must be 1–64 bytes long.
fn token(tokens: *std.mem.SplitIterator(u8, .scalar)) error{InvalidCommand}![]const u8 {
    const t = tokens.next() orelse return error.InvalidCommand;
    if (t.len == 0 or t.len > Cache.max_token_len) return error.InvalidCommand;
    return t;
}

fn end(tokens: *std.mem.SplitIterator(u8, .scalar)) error{InvalidCommand}!void {
    if (tokens.next() != null) return error.InvalidCommand;
}

